Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int MAXN = 7;
const int MOD = 1e9 + 7;
const int E100 = 570000004;
typedef long long LL;
int n, g[MAXN][MAXN];
LL nxt[1<<MAXN][1<<MAXN];
int bitcnt[1<<MAXN];

vector<int> S[MAXN+1];
int id[1<<MAXN];
map<LL, int> dp[MAXN]; 
int compute(int idx, LL mask) {
	if (mask == 0) return 0;
	if (idx == n) return 1;
	if (dp[idx].count(mask)) return dp[idx][mask];
	LL total_prob = 0;
	for (int subset_mask=0; subset_mask<(1<<n); ++subset_mask) {
		LL prob = 1;
		for (int j=0; j<n; ++j) {
			if (subset_mask & (1<<j))
				prob = g[idx][j] * prob % MOD;
			else
				prob = (1 - g[idx][j]) * prob % MOD;
		}
		LL new_mask = 0;
		for (int b=0; b<35; ++b) {
			if ((1LL << b) & mask)
				new_mask |= nxt[subset_mask][S[idx][b]];
		}
		total_prob = (total_prob + prob * compute(idx+1, new_mask)) % MOD;
	}
	return dp[idx][mask] = total_prob;
}

int main() {
	scanf("%d", &n);
	for (int i=0; i<n; ++i)
		for (int j=0; j<n; ++j) {
			scanf("%d", &g[i][j]);
			g[i][j] = g[i][j] * 1LL * E100 % MOD;
		}
	for (int i=1; i<(1<<n); ++i)
		bitcnt[i] = bitcnt[i ^ (i & -i)] + 1;
	for (int i=0; i<(1<<n); ++i) {
		id[i] = S[bitcnt[i]].size();
		S[bitcnt[i]].push_back(i);
	}
	for (int i=1; i<(1<<n); ++i)
		for (int j=0; j<(1<<n); ++j)
			for (int k=0; k<n; ++k)
				if ((i & (1<<k)) && !(j & (1<<k)))
					nxt[i][j] |= 1LL << id[j | (1<<k)];
	int answer = compute(0, 1);
	answer = (answer % MOD + MOD) % MOD;
	cout << answer << endl;
}
</original_code>
